import{_ as t,C as i,o as r,c as o,ag as n,E as s}from"./chunks/framework.cyF4XceO.js";const v=JSON.parse('{"title":"Specification","description":"","frontmatter":{},"headers":[],"relativePath":"spec/index.md","filePath":"spec/index.md"}'),c={name:"spec/index.md"};function d(l,e,h,p,m,f){const a=i("StatusNote");return r(),o("div",null,[e[0]||(e[0]=n('<h1 id="specification" tabindex="-1">Specification <a class="header-anchor" href="#specification" aria-label="Permalink to &quot;Specification&quot;">​</a></h1><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>An exact <strong>FormRef</strong> is the join of an API group, a kind, a definition version, and a schema digest. Compatibility is never inferred from a kind name alone: the same kind in a different epoch is a different contract. Form groups are namespaced into <a href="/spec/form-families.html">Form Families</a>; the Host API group is a protocol compatibility identity independent of any nested Form group.</p><table tabindex="0"><thead><tr><th>Surface</th><th>Identity</th></tr></thead><tbody><tr><td>Specification</td><td>Takoform 1.1; first numbered release identity; publication state is derived from the append-only numbered ledger and authority is one exact committed snapshot of the normative <code>spec/</code> tree (identity 1.0 was never published, is withdrawn, and may not be reused)</td></tr><tr><td>Current Form corpus</td><td><code>forms/candidates/current-family-index.json</code> (8 versionless families; 31 exact Experimental <code>0.x</code> Forms)</td></tr><tr><td>Host API candidate</td><td><code>forms.takoform.com/v1</code>, discovered at <code>/.well-known/takoform/v1</code> (separate and unpublished)</td></tr><tr><td>Current package envelope</td><td><code>packages.forms.takoform.com/v1alpha5</code> (unpublished)</td></tr><tr><td>Provider distribution</td><td>Independent: <strong>Provider 3.0.0</strong> is the current Registry-published non-normative reference implementation; Provider 2.1.1 is retained history</td></tr></tbody></table><p>Specification 1.1 does not publish or promote the separate Host API v1 candidate, relabel any current Form as <code>1.0.0</code>, publish a Form Package, mint a <code>/v1.1</code> or v2 lane, or release Provider 3. External Hosts, products, deployments, signers, and operators are optional adoption evidence rather than release authority.</p><p>The separately generated five-class compatibility report is compatibility evidence only. It is not part of the publication-evidence document, a release asset, or a prerequisite. W09 keeps C1 (normative freeze and executable tooling), C2 (evidence-only source snapshot), C3 (authoritative append-only publication receipt), and its direct-child C4 (bounded deterministic public refresh) as distinct linear boundaries. C4 cannot change normative source, evidence, ledgers, release tooling, Provider/Form/Host source, or unrelated files. W10 may write only future releases and may never reissue Specification 1.1.</p><p>The pre-Beta epochs (<code>forms.takoform.com/v1alpha1</code> and <code>/v1alpha2</code>) were withdrawn (<a href="/spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>); their identities are retired in the published ledgers and their bytes stay in repository history. The provider&#39;s SemVer is independent of every API identity, and no current central approval or admission derives from anything the withdrawn epochs published.</p><h2 id="current-lane-contracts" tabindex="-1">Current-lane contracts <a class="header-anchor" href="#current-lane-contracts" aria-label="Permalink to &quot;Current-lane contracts&quot;">​</a></h2><ul><li><a href="/spec/form-families.html">Form Families</a> — namespaced Form groups and the Edge Platform Family</li><li><a href="/spec/host-api/v1.html">Host API v1</a> — uid/generation/revision identity, long-running operations, fencing</li><li><a href="/spec/interface-contract/">Interface contracts</a> — exact capability contracts a Form&#39;s service exposes</li><li><a href="/spec/binding-contract/">Binding contracts</a> — typed outward capability use held by revisions</li><li><a href="/spec/artifact-transport/">Artifact transport</a> — content-addressed artifact upload and manifests</li></ul><h2 id="normative-schemas" tabindex="-1">Normative schemas <a class="header-anchor" href="#normative-schemas" aria-label="Permalink to &quot;Normative schemas&quot;">​</a></h2><p>The stable Host/API schema identities are reserved at <code>forms.takoform.com/schemas/...</code> by the append-only local contract lock:</p><ul><li><a href="/schemas/v1/form-ref.schema.json">form-ref v1</a></li><li><a href="/schemas/v1/form-definition.schema.json">form-definition v1</a></li><li><a href="/schemas/v1/host-api-wire.schema.json">host-api-wire v1</a></li><li><a href="/schemas/v1/host-discovery.schema.json">host discovery v1</a></li><li><a href="/schemas/v1alpha5/package-index.schema.json">package-index v1alpha5</a></li></ul><p>The withdrawn epochs&#39; schema identities are recorded as retired in <a href="/release/public-schema-identities.json"><code>release/public-schema-identities.json</code></a> and are never reused.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>A Form moves Proposal → Experimental → Stable → Legacy independently from the Specification. A future stable Form begins at <code>1.0.0</code> only through an explicit per-Form decision and its own evidence.</p><h2 id="more-surfaces" tabindex="-1">More surfaces <a class="header-anchor" href="#more-surfaces" aria-label="Permalink to &quot;More surfaces&quot;">​</a></h2><ul><li><a href="/proposals/">Proposals</a> — mutable design material for Forms that have not earned a public FormRef</li><li><a href="/forms/">Form inventory</a> — generated candidate and family inventory</li><li><a href="/conformance/">Conformance</a> — executable compatibility evidence</li><li><a href="/release/">Release</a> — independent Specification and Provider evidence tracks</li><li><a href="/docs/glossary.html">Glossary</a> — terms used across the documentation</li></ul>',17)),s(a)])}const y=t(c,[["render",d]]);export{v as __pageData,y as default};
